-- =====================================================================
--  51_bank_sinif11.sql : 11-CI SINIF - AZ DILI, INGILIS DILI,
--                        INFORMATIKA, AZERBAYCAN TARIXI
--
--  BU FAYL ELLE YAZILMIR - tools/sinif11.py yaradir:
--      python3 tools/sinif11.py
--
--  Az dili 8 + Ingilis dili 6 + Informatika 5 + Tarix 6
--  az/ing/tarix 20 movzu x 30 + inf 5 movzu x 20 = 700.
--  ext_key: az11-/ing11-/inf11-/tarix11-...
--  ON SERT: 49_movzular_orta11.sql islenmis olmalidir.
--  SONRA:   05_grants.sql yeniden islet.
-- =====================================================================

do $$
begin
  if not exists (select 1 from public.topics t join public.subjects s
      on s.id = t.subject_id
     where (s.slug, t.slug) in (('az-dili','az-11-uslubiyyat'),
                                ('ingilis-dili','ing-11-whys'),
                                ('informatika','inf-11-sistemler'),
                                ('tarix','tarix-11-zefer'))
     having count(*) = 4) then
    raise exception 'ONCE 49_movzular_orta11.sql isledilmelidir.';
  end if;
end $$;

delete from public.question_options o
 using public.questions q
 where o.question_id = q.id
   and q.owner_type = 'platform'
   and (q.ext_key like 'az11-%' or q.ext_key like 'ing11-%'
        or q.ext_key like 'inf11-%' or q.ext_key like 'tarix11-%');

